"""Cards and headline figures for Vietnam's twelve spine chapters."""
from __future__ import annotations

MONEY, WORLD, PEOPLE = "money", "world", "people"


def headline(ctx):
    return [
        ctx.stat({"vi":"GDP","en":"GDP","pt":"PIB"}, [(y,v/1e9) for y,v in ctx.col("international/gdp_usd_wb.csv","gdp_usd")], "usd_bn"),
        ctx.stat({"vi":"GDP bình quân đầu người","en":"GDP per person","pt":"PIB por pessoa"}, ctx.col("international/gdp_usd_wb.csv","gdp_per_person_usd"), "count", kind="level"),
        ctx.stat({"vi":"Dân số","en":"Population","pt":"População"}, [(y,v/1000) for y,v in ctx.col("demography/population.csv","population_total_thousand")], "pop_mn", kind="level"),
        ctx.stat({"vi":"Tăng trưởng thực","en":"Real growth","pt":"Crescimento real"}, ctx.col("macro/gdp.csv","real_growth_pct"), "pct_s"),
        ctx.stat({"vi":"Lạm phát","en":"Inflation","pt":"Inflação"}, [(y,v-100) for y,v in ctx.col("macro/cpi.csv","cpi")], "pct"),
        ctx.stat({"vi":"Dự trữ","en":"Official reserves","pt":"Reservas oficiais"}, [(y,v/1e9) for y,v in ctx.col("international/reserves.csv","reserves_usd")], "usd_bn", kind="level"),
        ctx.stat({"vi":"Mức sinh","en":"Fertility rate","pt":"Taxa de fecundidade"}, ctx.col("demography/vital_rates.csv","tfr_total"), "count", kind="level"),
    ]


def build(ctx):
    T, S = ctx.text, ctx.stat
    specs = [
        ("01-economy","economy",MONEY,{"vi":"Kinh tế","en":"The Economy","pt":"A Economia"},{"vi":"Tăng trưởng nhanh đi cùng một lần đổi quy mô GDP và các cú sốc giá lớn.","en":"Fast growth sits beside a GDP-scale change and large price shocks.","pt":"O crescimento rápido convive com uma mudança de escala do PIB e grandes choques de preços."}, S({"vi":"Tăng trưởng thực","en":"Real growth","pt":"Crescimento real"},ctx.col("macro/gdp.csv","real_growth_pct"),"pct_s")),
        ("02-fiscal","fiscal",MONEY,{"vi":"Tài chính công","en":"Public Finances","pt":"Contas Públicas"},{"vi":"Tài khoản chính phủ chung và ngân sách nhà nước được trình bày riêng.","en":"General-government accounts and the state budget remain separate.","pt":"As contas do governo geral e o orçamento estatal permanecem separados."}, S({"vi":"Nợ gộp","en":"Gross debt","pt":"Dívida bruta"},ctx.col("fiscal/debt_balance.csv","gross_debt_pct_gdp"),"pct_gdp",kind="level")),
        ("03-spending","spending",MONEY,{"vi":"Chi tiêu và đầu tư","en":"Spending and Investment","pt":"Gasto e Investimento"},{"vi":"Các đầu mục ngân sách quốc gia cho thấy những gì được công bố và những gì còn thiếu.","en":"National budget heads show both what is published and what remains absent.","pt":"As rubricas nacionais mostram o que é publicado e o que continua ausente."}, S({"vi":"Tỷ lệ đầu tư","en":"Investment rate","pt":"Taxa de investimento"},ctx.col("macro/gdp.csv","fixed_assets_pct_gdp"),"pct_gdp",kind="level")),
        ("04-trade","trade",WORLD,{"vi":"Thương mại","en":"Trade","pt":"Comércio"},{"vi":"Xuất khẩu lớn nhưng cán cân với Hoa Kỳ và Trung Quốc đi ngược chiều.","en":"Exports are large, while the US and China balances point in opposite directions.","pt":"As exportações são grandes, enquanto os saldos com EUA e China apontam em direções opostas."}, S({"vi":"Xuất khẩu","en":"Goods exports","pt":"Exportações de bens"},[(y,v/1000) for y,v in ctx.col("trade/totals.csv","exports_usd_mn")],"usd_bn")),
        ("05-markets","markets",MONEY,{"vi":"Thị trường","en":"Markets","pt":"Mercados"},{"vi":"Lịch sử lãi suất chính sách còn chờ; đồng Việt Nam và VN-Index vẫn có thể so sánh.","en":"The policy-rate history remains pending; the đồng and VN-Index stay comparable.","pt":"A história da taxa de política segue pendente; o đồng e o VN-Index permanecem comparáveis."}, S({"vi":"VN-Index","en":"VN-Index","pt":"VN-Index"},ctx.col("markets/vnindex.csv","close"),"count",kind="level")),
        ("06-credit","credit",MONEY,{"vi":"Tín dụng và tiền tệ","en":"Credit and Money","pt":"Crédito e Moeda"},{"vi":"Nợ hộ gia đình còn chờ; tín dụng toàn nền kinh tế chỉ nằm trong ô góc nhìn riêng.","en":"Household debt remains pending; economy-wide credit appears only in the country lens.","pt":"A dívida familiar segue pendente; o crédito da economia aparece apenas na lente do país."}, S({"vi":"Nợ xấu","en":"Non-performing loans","pt":"Crédito inadimplente"},ctx.col("credit/credit_adb.csv","npl_ratio_pct"),"pct",kind="level")),
        ("07-people","people",PEOPLE,{"vi":"Con người và thu nhập","en":"People and Incomes","pt":"Pessoas e Renda"},{"vi":"Đường Gini và nghèo đói được tách tại các thay đổi phương pháp.","en":"Gini and poverty lines split where survey methods and standards change.","pt":"As linhas de Gini e pobreza se separam quando métodos e padrões mudam."}, S({"vi":"Gini","en":"Gini","pt":"Gini"},[(y,v*100) for y,v in ctx.col("social/gini.csv","gini_national_2020_on")],"count",kind="level")),
        ("08-world","world",WORLD,{"vi":"Việt Nam trong thế giới","en":"Vietnam in the World","pt":"Vietnã no Mundo"},{"vi":"Các chỉ số quốc tế được đặt cạnh cách đo của Việt Nam.","en":"International comparables sit beside Vietnam's own measures.","pt":"Os comparáveis internacionais aparecem ao lado das medidas vietnamitas."}, S({"vi":"HDI","en":"HDI","pt":"IDH"},ctx.col("international/hdi_undp.csv","hdi"),"count",kind="level")),
        ("09-demography","demography",PEOPLE,{"vi":"Dân số học","en":"Demography","pt":"Demografia"},{"vi":"Mức sinh dưới thay thế làm chậm đà tăng dân số.","en":"Below-replacement fertility slows population growth.","pt":"A fecundidade abaixo da reposição desacelera o crescimento populacional."}, S({"vi":"Tổng tỷ suất sinh","en":"Fertility rate","pt":"Taxa de fecundidade"},ctx.col("demography/vital_rates.csv","tfr_total"),"count",kind="level")),
        ("10-security","security",PEOPLE,{"vi":"An ninh và giao thông","en":"Security and Road Safety","pt":"Segurança e Trânsito"},{"vi":"Các mô hình quốc tế bổ sung cho số liệu cảnh sát và tư pháp hạn chế.","en":"International models supplement limited police and justice counts.","pt":"Modelos internacionais complementam contagens policiais e judiciais limitadas."}, S({"vi":"Tử vong giao thông","en":"Road deaths","pt":"Mortes no trânsito"},ctx.col("security/road_deaths.csv","road_deaths_per_100k"),"per100k",kind="level")),
        ("11-mortality","mortality",PEOPLE,{"vi":"Tử vong","en":"Mortality","pt":"Mortalidade"},{"vi":"Sổ đăng ký ngắn không đủ cho đường cơ sở 2015–2019; ước tính nguyên nhân WHO vẫn tách riêng.","en":"The short register cannot supply the 2015–2019 baseline; WHO cause estimates stay separate.","pt":"O registro curto não permite a base 2015–2019; as estimativas de causas da OMS ficam separadas."}, S({"vi":"Tỷ suất chết thô","en":"Crude death rate","pt":"Taxa bruta de mortalidade"},ctx.col("demography/vital_rates.csv","cdr_total_per_mille"),"count",kind="level")),
        ("12-migration","migration",WORLD,{"vi":"Di cư","en":"Migration","pt":"Migração"},{"vi":"Tồn lượng và mô hình được giữ riêng; không có dòng di cư quốc tế được bịa ra.","en":"Stocks and models stay separate; no international flow is invented.","pt":"Estoques e modelos ficam separados; nenhum fluxo internacional é inventado."}, S({"vi":"Người Việt ở nước ngoài","en":"Vietnamese emigrants","pt":"Emigrantes vietnamitas"},[(y,v/1e6) for y,v in ctx.col("migration/migrant_stock.csv","emigrants_world")],"pop_mn",kind="level")),
    ]
    out=[]
    for ident,topic,family,title,blurb,stat in specs:
        out.append({"id":ident,"topic":topic,"n":ident[:2],"family":family,"title":T(**title),"blurb":T(**blurb),"stats":[stat]})
    return out
